import hashlib
import math

class BloomFilter:
    """
    A bloom filter implementation using an optimal number of hash functions
    and a bit array calculated based on the expected number of items and
    the desired false positive rate. 
    This design leverages simple integer arithmetic and bitwise operations 
    to manage space and time efficiency.
    """

    def __init__(self, expected_items: int, false_positive_rate: float) -> None:
        if expected_items <= 0:
            raise ValueError("Expected items must be greater than 0.")
        if not (0 < false_positive_rate < 1):
            raise ValueError("False positive rate must be between 0 and 1.")

        self.expected_items = expected_items
        self.false_positive_rate = false_positive_rate

        self.size = self._calculate_size()
        self.num_hashes = self._calculate_num_hashes()

        self.bit_array = [0] * self.size

    def _calculate_size(self) -> int:
        """ Calculates the size of the bit array. """
        return math.ceil(- (self.expected_items * math.log(self.false_positive_rate)) / (math.log(2) ** 2))

    def _calculate_num_hashes(self) -> int:
        """ Calculates the optimal number of hash functions. """
        return math.ceil((self.size / self.expected_items) * math.log(2))

    def _hashes(self, item: str) -> list:
        """ Generate hash indices for the given item. """
        hashes = []
        for i in range(self.num_hashes):
            hash_result = hashlib.md5((item + str(i)).encode()).hexdigest()
            index = int(hash_result, 16) % self.size
            hashes.append(index)
        return hashes

    def add(self, item: str) -> None:
        """ Adds an item to the bloom filter. """
        for index in self._hashes(item):
            self.bit_array[index] = 1

    def contains(self, item: str) -> bool:
        """ Checks if an item is possibly in the bloom filter. """
        for index in self._hashes(item):
            if self.bit_array[index] == 0:
                return False
        return True

import hashlib
import math

class BloomFilter:
    """
    A Bloom Filter implementation that uses a fixed-size bit array and multiple hash functions.

    The number of bits in the bit array is calculated based on the expected_items and false_positive_rate,
    along with the optimal number of hash functions to minimize the false positive rate for the given parameters.
    """

    def __init__(self, expected_items: int, false_positive_rate: float) -> None:
        self.num_bits = self._calculate_num_bits(expected_items, false_positive_rate)
        self.num_hashes = self._calculate_num_hashes(expected_items, self.num_bits)
        self.bit_array = [0] * self.num_bits

    def _calculate_num_bits(self, n: int, p: float) -> int:
        """Calculates the size of the bit array."""
        return math.ceil(-(n * math.log(p)) / (math.log(2) ** 2))

    def _calculate_num_hashes(self, n: int, m: int) -> int:
        """Calculates the optimal number of hash functions."""
        return max(1, round((m / n) * math.log(2)))

    def _hashes(self, item: str) -> list:
        """Generates a list of hash values for the provided item."""
        return [int(hashlib.md5(item.encode()).hexdigest(), 16) % self.num_bits + i for i in range(self.num_hashes)]

    def add(self, item: str) -> None:
        """Adds an item to the Bloom filter."""
        for hash_value in self._hashes(item):
            self.bit_array[hash_value] = 1

    def contains(self, item: str) -> bool:
        """Checks if an item is possibly in the Bloom filter."""
        return all(self.bit_array[hash_value] for hash_value in self._hashes(item))
